import React, { Component } from "react";
import queryString from "query-string";
import EventEmitter from "./libs/EventEmitter";
import translate from "./libs/translations";
import ReactMustache from "react-mustache";
import settingsGetter from "./libs/settingsGetter";
import FormMain from "./libs/FormMain";
import Mustache from "mustache";

class Results extends Component {
  constructor() {
    let params = queryString.parse(window.location.search);
    super();
    const structuredSearchProps = window.mw?.config.get("structuredSearchProps") || {};

    this.state = {
      searchStarted: !!params.advanced_search,
      searchReturned: false,
      hasInputHidden: structuredSearchProps.input === "hidden" || "",
      resultClass: structuredSearchProps.class || "",
      displayTemplate: structuredSearchProps.display || "",
      trimWordsCount: 20, // Default value
    };

    // Translations
    this.loadTranslations();

    EventEmitter.on("searchStarted", (data) => {
      this.handleSearchStarted(data);
    });

    EventEmitter.on("dataRecieved", (data) => {
      this.handleDataReceived(data);
    });

    settingsGetter.get().then((data) => {
      if (data) {
        this.templates = data.templates;
      }
    });
  }

  componentDidMount() {
    // Set `trimWordsCount` from global config
    let wordLimit = mw.config.get("wgOverrideStructuredSearchWordNum") || mw.config.get("wgAutocompleteIsStructuredSearchWordNum") || 20;
    this.setState({ trimWordsCount: parseInt(wordLimit, 10) || 20 });
  }

  loadTranslations() {
    translate("structuredsearch-no-results").then((t) => (this.noResults = t));
    translate("structuredsearch-on-results-error").then((t) => (this.noResultsError = t));
    translate("structuredsearch-next").then((t) => (this.nextText = t));
    translate("structuredsearch-on-search-text").then((t) => (this.onSearchText = t));
    translate("structuredsearch-results-sum").then((t) => (this.resultsSumText = t));
  }

  handleSearchStarted(data) {
    let paramsToChange = {
      searchStarted: true,
      onTop: data.reset,
      searchReturned: false,
    };

    if (data.reset) {
      paramsToChange.results = [];
      paramsToChange.lastIsError = false;
      paramsToChange.total = 0;
      setTimeout(() => this.scrollUp(), 200);
    }

    this.setState(paramsToChange);
  }

  handleDataReceived(data) {
    let results = data.results;

    if (results && results.error) {
      this.setState({
        lastIsError: true,
        results: [],
        searchReturned: true,
        searchStarted: false,
        onTop: false,
      });
    } else {
      let newResults = data.reset ? results : { ...this.state.results, ...results };
      let newTotal = data.searchinfo?.totalhits || 0;

      let processedResults = Object.values(newResults).map((item) => {
        let result = {
          title: item.short_title,
          full_title: item.full_title || item.title,
          namespace: item.namespace,
          image: item.page_image_ext,
          snippet: this.truncateWords(item.snippet, this.state.trimWordsCount), // Corrected reference
          link: item.page_link,
          category: item.category,
          type: "richResult",
        };

        this.linkToTheSearchTerms(result); // Process search term linking
        return result;
      });

      this.setState({
        offset: data.continue ? data.continue.sroffset : null,
        total: newTotal,
        lastIsError: false,
        results: processedResults,
        searchReturned: true,
        searchStarted: false,
        onTop: false,
      });
    }
  }

  truncateWords(str, maxWords) {
    let words = str.split(" ");
    return words.length > maxWords ? words.slice(0, maxWords).join(" ") + "..." : str;
  }

  linkToTheSearchTerms(result) {
    if (result.snippetReplaced) {
      return;
    }

    let tempContainer = document.createElement("div");
    tempContainer.innerHTML = result.snippet;

    let allSpansInResultSnippet = tempContainer.querySelectorAll(".searchmatch");
    let title = result.full_title || result.title;

    for (let span of allSpansInResultSnippet) {
      let a = document.createElement("a");
      let textContent = span.textContent.trim();
      a.text = textContent;
      a.href = `${title}#:~:text=${encodeURIComponent(textContent)}`;
      span.replaceWith(a);
    }

    result.snippet = tempContainer.innerHTML;
    result.snippetReplaced = true;
  }

  getTemplateByResult(result) {
    let ns = result.namespaceId;
    const displayTemplate = this.state.displayTemplate?.trim() || FormMain.getValue("display");

    if (displayTemplate && this.templates?.[displayTemplate]) {
      return this.templates[displayTemplate];
    }

    return this.templates?.["template_" + ns] || this.templates?.["default"] || null;
  }

  getResultJsx(result) {
    let template = this.getTemplateByResult(result);
    if (!template) return null;

    return (
      <div
        ref={(el) => {
          if (el) {
            el.innerHTML = Mustache.render(template, result);
            let firstChild = el.firstElementChild;
            if (firstChild) {
              el.replaceWith(...el.childNodes);
            }
          }
        }}
      />
    );
  }

  scrollUp() {
    window.scrollTo({ top: 0, left: 0, behavior: "smooth" });
  }

  next() {
    FormMain.setNext(this.state.offset);
  }

  render() {
    let results = [],
      errorHtml,
      nextButton,
      resultsSum = "",
      searchTop = "",
      searchBottom = "";

    if (this.state.searchStarted) {
      searchTop = this.state.onTop ? <div className="loading loading-top" dangerouslySetInnerHTML={{ __html: this.onSearchText }}></div> : "";
      searchBottom = !this.state.onTop ? <div className="loading loading-bottom" dangerouslySetInnerHTML={{ __html: this.onSearchText }}></div> : "";
    }

    if (this.state.results) {
      results = Object.values(this.state.results).map((result) => this.getResultJsx(result));

      if (this.state.searchReturned && !results.length) {
        errorHtml = <div className={`no-results ${this.state.lastIsError ? "no-results-error" : "no-results-empty"}`} dangerouslySetInnerHTML={{ __html: this.state.lastIsError ? this.noResultsError : this.noResults }}></div>;
      }

      if (this.state.offset && results.length) {
        nextButton = <button type="button" onClick={this.next.bind(this)} dangerouslySetInnerHTML={{ __html: this.nextText }}></button>;
      }
    }

    if (!this.state.hasInputHidden && results.length && this.resultsSumText && this.state.total) {
      resultsSum = <div className="results-sum-message" dangerouslySetInnerHTML={{ __html: this.resultsSumText.replace("$1", this.state.total) }}></div>;
    }

    return <div className={`results ${this.state.resultClass}`}>{searchTop}{resultsSum}{results}{errorHtml}{nextButton}{searchBottom}</div>;
  }
}

export default Results;
